bool spatialDepth(const CoinRenderCapabilities&caps,unsigned samples){SpatialHarness h(caps,samples);if(!h.target)return false;SpatialScene s(2,255);s.paint(false);Frame a,b,offset,back;bool ok=h.render(s.root,a,"spatial default depth");if(!ok)return false;auto*depth=new SoDepthBuffer;depth->range.setValue(.2f,.8f);s.receiver->insertChild(depth,0);auto*polygon=new SoPolygonOffset;polygon->styles=SoPolygonOffset::FILLED;polygon->factor=1;polygon->units=1;polygon->on=FALSE;s.receiver->insertChild(polygon,1);if(h.render(s.root,b,"spatial custom depth range")){unsigned tested=0,bad=0;for(int y=32;y<96;++y)for(int x=32;x<96;++x){size_t p=size_t(y*side+x);bad+=std::abs(b.depth[p]-(.2f+.6f*a.depth[p]))>2e-5f;++tested;}ok &=check(tested>0&&bad==0,"custom depth range maps independent default depth linearly");}else ok=false;polygon->on=TRUE;ok &=h.render(s.root,offset,"spatial enabled polygon offset");if(offset.depth.size()==b.depth.size()){unsigned changed=0;for(size_t p=0;p<b.depth.size();++p)changed+=offset.depth[p]>b.depth[p];ok &=check(changed>100,"spatial polygon offset effectively changes depth");}polygon->on=FALSE;ok &=h.render(s.root,back,"spatial custom depth restore")&&exact(b,back);depth->range.setValue(std::numeric_limits<float>::quiet_NaN(),.8f);ok &=h.reject(s.root,b,"spatial invalid custom depth");depth->range.setValue(.2f,.8f);ok &=h.render(s.root,back,"spatial depth recovery")&&exact(b,back);s.receiver->removeChild(polygon);s.receiver->removeChild(depth);ok &=h.render(s.root,back,"spatial default depth restored")&&exact(a,back);return ok;}

