  if(kind==1){std::vector<uint8_t>bad(3*2*4,255);s.cube[7]->imageNegZ.setValue(SbVec2s(3,2),4,bad.data());ok &=h.reject(s.root,stable,"malformed NPOT cube face");s.paint(false);ok &=h.render(s.root,back,"cube face recovery")&&exact(stable,back);}
